import{_ as e,o,c as r,ai as d}from"./chunks/framework.Ci0kozOl.js";const g=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/introduction/glossary.md","filePath":"3.0/introduction/glossary.md","lastUpdated":1785947307000}'),a={name:"3.0/introduction/glossary.md"};function s(n,t,i,c,l,p){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Terms used throughout UnoPim and this documentation, in alphabetical order.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>ACL</strong></td><td>Access Control List — permission keys (<code>catalog.products.create</code>) checked per route and per UI action. Admin ACL and API ACL are separate trees.</td></tr><tr><td><strong>Association Type</strong></td><td>A named product-to-product relationship (built-in: related, up-sells, cross-sells; custom types since 3.0) optionally carrying per-link fields.</td></tr><tr><td><strong>Attribute</strong></td><td>A typed data field on products (<code>text</code>, <code>select</code>, <code>price</code>, <code>image</code>, <code>date</code>, <code>boolean</code>, <code>measurement</code>, …) with per-channel/per-locale scoping flags.</td></tr><tr><td><strong>Attribute Family</strong></td><td>The schema a product follows: which attributes it has, grouped into attribute groups, and which are required for completeness.</td></tr><tr><td><strong>Channel</strong></td><td>A distribution context (webshop, print, marketplace) with its own set of enabled locales and currencies.</td></tr><tr><td><strong>Completeness</strong></td><td>The per-channel, per-locale score of how many required attributes a product has filled.</td></tr><tr><td><strong>Configurable Product</strong></td><td>A product with variants, generated over one or two axes (e.g. colour × size).</td></tr><tr><td><strong>Data Carrier</strong></td><td>The physical link from product to passport — in UnoPim, a QR code (SVG) encoding the GS1 Digital Link or passport URL.</td></tr><tr><td><strong>DPP (Digital Product Passport)</strong></td><td>A structured public record of a product&#39;s compliance data, published per locale with immutable versions.</td></tr><tr><td><strong>GS1 Digital Link</strong></td><td>The retail-industry standard for GTIN-based URLs (<code>/01/{gtin}</code>) resolving to product information.</td></tr><tr><td><strong>GTIN</strong></td><td>Global Trade Item Number — 8/12/13/14-digit product identifier with a check digit; validated on save when passports are enabled.</td></tr><tr><td><strong>Locale</strong></td><td>A language/region combination (<code>en_US</code>, <code>de_DE</code>) enabled per channel; also the unit of localization for names, labels, and values.</td></tr><tr><td><strong>Measurement Family</strong></td><td>A group of units (Length: mm, cm, m…) with conversion rules to a standard unit.</td></tr><tr><td><strong>Proxy Model</strong></td><td>Concord&#39;s extension mechanism: models resolve through <code>*Proxy</code> classes so packages can override core models without editing them.</td></tr><tr><td><strong>Publication</strong></td><td>The generic publishing engine underneath passports: immutable versions, public routes, tiers, tombstones.</td></tr><tr><td><strong>Repository</strong></td><td>The data-access layer (<code>prettus/l5-repository</code> based) — controllers talk to repositories, not Eloquent directly.</td></tr><tr><td><strong>Robot User</strong></td><td>A dedicated <code>type = &#39;api&#39;</code> admin account owning an API integration; cannot log into the panel.</td></tr><tr><td><strong>Scope</strong></td><td>The channel/locale context a value belongs to — one of <code>common</code>, <code>locale_specific</code>, <code>channel_specific</code>, <code>channel_locale_specific</code>. See <a href="./../architecture/data-model.html">Data Model</a>.</td></tr><tr><td><strong>Tier (access tier)</strong></td><td>Passport data visibility level: <code>consumer</code> (public), <code>operator</code>, <code>authority</code> — elevated tiers open via signed, expiring links.</td></tr><tr><td><strong>Values document</strong></td><td>The JSON column <code>products.values</code> holding all attribute data for a product, partitioned by scope.</td></tr><tr><td><strong>Variant Group</strong></td><td>The internal intermediate product type in two-level variant structures (level-1 axis node).</td></tr><tr><td><strong>Variant Structure</strong></td><td>A family-level definition of variant axes and attribute placements across <code>common</code> / <code>sub_parent</code> / <code>variant</code> levels.</td></tr></tbody></table>',3)])])}const h=e(a,[["render",s]]);export{g as __pageData,h as default};
